            listOf("Шурх... Озирнувся? Хе-хе.", "Жовтий — колір тривоги. І гарбузів.", "Найкрасивіше листя — те, що вже впало.")),
        Pet(30, "Сніжинка", "Ще одне патетичне чарівнятко.",
            "Привіт. Ти знаєш, що сніжинки унікальні? У світі немає жодної такої, як я! Ну... хіба що мільярд дуже схожих. Але я — особлива. Подивись, як я виблискую. Ні, ближче. Ще ближче!",
            "Прогулюйтесь протягом 15 хв взимку.", 0.15, R(steps = 1000, months = WINTER),
            listOf("Я не тану. Я драматично зникаю.", "Кожна сніжинка особлива. Але я — найособливіша.", "Не дихай на мене!")),
        Pet(31, "Ангелятко", "Найнатхненніша захисниця людей.",
            "Запам'ятай! Світло в серці твоєму сильніше за будь-яку хмару. А сьогодні хмар немає зовсім — тож світла вдвічі більше! Я завжди поруч, навіть коли мене не видно.",
            "Прогулюйтесь протягом 30 хв в ясну погоду.", 1.0, R(steps = 2000, weather = setOf(CLEAR)),
            listOf("Сонце сьогодні світить для тебе.", "Я пильную. Йди сміливо!", "Не забудь панамку!")),
        Pet(32, "Хмареня", "Хмари плану не мають!",
            "Слухай, мандрівнику... Хмари плану не мають! Сьогодні я зайчик, завтра кит, а післязавтра просто сіра ковдра. Я й сам не знаю, ким стану. І це чудово!",
            "Прогулюйтесь протягом 30 хв в хмарну погоду.", 1.0, R(steps = 2000, weather = setOf(CLOUDY)),
            listOf("Бачиш он ту хмару? Це я позую.", "Плани — для тих, хто не вміє літати.", "Може, дощ. А може, ні. Хто знає?")),
        Pet(33, "Дощовинка", "Дружелюбна і допитлива.",
            "О, небо високо десь там! А я тут, у калюжі, з тобою! Ти теж любиш дощ? Калюжі — це маленькі дзеркала неба. Стрибнімо в оту, найбільшу?",
            "Прогулюйтесь протягом 15 хв в дощову погоду.", 1.0, R(steps = 1000, weather = setOf(RAIN)),
