        Pet(34, "Туманюсик", "Пухнаста бубочка.",
            "Привіт. Туман надає загадковості... і ховає мене. Тому мене так рідко знаходять. А ти знайшов! Ти, мабуть, дуже уважний. Або просто наступив на мене. Нічого, я м'який.",
            "Прогулюйтесь протягом 15 хв в туманну погоду.", 1.0, R(steps = 1000, weather = setOf(FOG)),
            listOf("Ти мене бачиш? А зараз?", "Я не губляюся. Я загадковий.", "Пух-пух! Туман густішає.")),
        Pet(35, "Шурхотун", "Еталон грації та легкості.",
            "Дозволь шепоту вітру вести тебе... Ось так, легко, наче пір'їнка. Влітку вітер грається з листям, з волоссям, з повітряними зміями. А я граюся з вітром.",
            "Прогулюйтесь протягом 15 хв в вітряну погоду влітку.", 1.0, R(steps = 1000, months = SUMMER, minWindKph = 15.0),
