        Pet(36, "Сніжничок", "Не рекомендується не ліпити сніговика!",
            "Привіт! Я Сніжничок. Головне правило зими: падає сніг — ліпи сніговика. Не рекомендується його не ліпити! Я серйозно, це майже закон. Морква в тебе є?",
            "Прогулюйтесь протягом 15 хв в сніжну погоду.", 1.0, R(steps = 1000, weather = setOf(SNOW)),
            listOf("Сніжка в тебе! Ой, вибач.", "Три грудки — і новий друг готовий.", "Зима без сніговика — як чай без варення.")),
        Pet(37, "Ням-нямка", "Енергійне, люб'язне. Смачне…",
            "Привіт-привіт! Яка тепла днинка! Саме час для морозива, пікніка і... ні-ні, не їж мене! Я енергійна, люб'язна і, так, трохи смачна на вигляд. Але я друг, а не десерт!",
            "Прогулюйтесь протягом 30 хв в теплу погоду.", 1.0, R(steps = 2000, minTempC = 15.0, maxTempC = 26.0),
            listOf("Я не тістечко! Хоча пахну ваніллю.", "Тепло — це смачно!", "Ням-ням! Це я радію.")),
        Pet(38, "Кактусеня", "З розумінням ставиться до спеки.",
            "Доброго дня! Спекотно? А мені якраз! Поки всі ховаються в тінь, я засмагаю. Тільки не обіймай мене, будь ласка. Я люблю обійми, просто... голки.",
            "Прогулюйтесь протягом 15 хв в спекотну погоду.", 1.0, R(steps = 1000, minTempC = 26.0),
            listOf("Пий воду! Я от п'ю раз на місяць.", "Колючий зовні, ніжний всередині.", "+30? Прохолодненько.")),
        Pet(39, "Котон", "Інтроверт, домосід.",
            "Привіт! Ти таки виманив мене надвір. Взагалі-то я домосід: плед, какао, книжка. Але прохолодна погода — це компроміс: можна погуляти й не спітніти. Тільки недовго, гаразд?",
            "Прогулюйтесь протягом 15 хв в прохолодну погоду.", 1.0, R(steps = 1000, minTempC = 0.0, maxTempC = 15.0),
