        Pet(40, "Паморозь", "Вважає себе головною в країні іроній.",
            "Ох, знову ти з'явився? Яка несподіванка. Вийти гуляти в мороз — геніальна ідея, аплодую. Не хвилюйся, червоні щоки нині в моді. Ну, ходімо, раз уже прийшов.",
            "Прогулюйтесь протягом 15 хв в морозну погоду.", 1.0, R(steps = 1000, maxTempC = 0.0),
            listOf("О, ти змерз? Шок.", "Я не холодна. Я просто стримана.", "Чудова погода. Для пінгвінів.")),
        Pet(41, "Дюдя", "Замкнена істота.",
            "Як ви мене помітили? Я ж так старанно ховався... Морозного ранку, коли сонце тільки сходить, я виходжу помилуватися інеєм. Тільки нікому не кажіть, що бачили мене, гаразд?",
            "Прогулюйтесь протягом 15 хв ясним морозним ранком.", 1.0, R(steps = 1000, hours = 5 to 9, weather = setOf(CLEAR), maxTempC = 0.0),
            listOf("Тсс. Мене тут немає.", "Іній блищить — і я трошки теж.", "Можна я постою за тобою?")),
        Pet(42, "Тон", "Ентузіаст і екоактивіст.",
            "Вітаю тебе, подорожній. Знаєш, чому я люблю холодний дощ? Він напуває землю, очищає повітря й розганяє автомобілі. А ти обрав іти пішки — природа тобі дякує! І я теж.",
            "Прогулюйтесь 15 хв в холодну дощову погоду.", 1.0, R(steps = 1000, weather = setOf(RAIN), minTempC = -5.0, maxTempC = 15.0),
            listOf("Кожен крок пішки — плюс одне щасливе дерево.", "Сортуй сміття! І думки теж.", "Дощ — безкоштовний полив для всієї планети.")),
        Pet(43, "Ропавк", "Миле чарівнятко.",
            "Ква-ква! (Тобто «доброго дощового ранку!») Ранок, дощик, калюжі — що може бути краще? Хіба що комарик на сніданок. Хочеш, навчу квакати? Дуже корисно для дихання.",
            "Прогулюйтесь 15 хв дощовим ранком.", 1.0, R(steps = 1000, hours = 5 to 11, weather = setOf(RAIN)),
            listOf("Ква! Ква-ква! (Ти чудовий!)", "Калюжа — мій басейн.", "Стрибай зі мною!")),
        Pet(44, "Сніжниця", "Майстер снігових шедеврів.",
            "Привіт! Що за несподівана зустріч! Хто ж гуляє в таку хуртовину? Лише справжні герої та я. Я якраз ліплю снігову скульптуру — бачиш? Ні? Це вітер щойно її здув. Мистецтво мінливе!",
            "Прогулюйтесь 5 хв в хуртовину.", 1.0, R(steps = 400, weather = setOf(BLIZZARD)),
