        Pet(45, "Мур-Мряка", "Зверхнє створіння.",
            "Так-так-так... погляньмо, хто тут. Людина, яка вийшла гуляти в п'ятницю тринадцятого. Сміливо. Або нерозважливо. Я чорна кішка удачі, і ще не вирішила, на чиєму я боці. Мур.",
            "Прогулюйтесь в п'ятницю 13 протягом 15 хв.", 1.0, R(steps = 1000, days = setOf(FRIDAY), dayOfMonth = 13),
            listOf("Перейти тобі дорогу? Подумаю.", "Мур. Це не ласка. Це попередження.", "Удача любить сміливих. А я — тільки себе.")),

        Pet(46, "Зая", "Любителька екзотичних схованок з яйцями!",
            "Привіт-привіт! Я сховала крашанки по всьому місту! Одна під лавкою, друга в кущах, третя... ой, здається, я її з'їла. Великдень — свято, коли пошуки — найкраща розвага!",
            "Прогулюйтесь на Великдень протягом 15 хв.", 1.0, R(steps = 1000, holiday = Holiday.EASTER),
            listOf("Холодно... тепліше... гаряче!", "Писанка — це яйце, яке вміє малювати.", "З Великоднем! Знайшов крашанку?")),
        Pet(47, "Рябка", "Планування від 'А' до 'Я'.",
            "Привіт! А чи підготував ти плани? На місяць? На тиждень? На сьогодні? У мене все розписано від «А» до «Я»: пункт перший — зустріти тебе. Виконано! Пункт другий — ще тисяча кроків...",
