        Pet(49, "Ціпа", "Позитивна і мила.",
            "Привіт. Любиш гратися в піжмурки? Я дуже! Особливо на Великдень, коли всюди ховають крашанки. Раз, два, три, чотири, п'ять — я іду шукать!",
            "Прогулюйтесь на Великдень протягом 15 хв.", 1.0, R(steps = 1000, holiday = Holiday.EASTER),
            listOf("Знайшла! Ой, це камінець.", "Ціп-ціп! Твоя черга ховатися.", "З Великоднем!")),
        Pet(50, "Пряничок", "Справжній оптиміст.",
            "Привіт. Різдво — найкраща пора! Пахне корицею, мандаринами та ялинкою. Мене спекли з любов'ю й краплею меду, тому в мене завжди гарний настрій. Навіть коли хтось намагається мене з'їсти.",
            "Прогулюйтесь на Різдво протягом 15 хв.", 1.0, R(steps = 1000, holiday = Holiday.CHRISTMAS),
            listOf("Колядки — найкраща музика!", "Я не крихкий. Я хрусткий!", "Веселих свят!")),
        Pet(51, "Сніжуня", "Має різкий соціальний характер.",
            "Сніг буває таким красивим... доки хтось у нього не наступить. Так-так, я про тебе. Вихідні, сніг — і всі кидаються ліпити, кататися, галасувати. А я хочу тиші. Але з тобою, мабуть, можна.",
            "Прогулюйтесь 15 хв у зимовий вікенд коли сніг.", 1.0, R(steps = 1000, days = setOf(SATURDAY, SUNDAY), months = WINTER, weather = setOf(SNOW)),
            listOf("Не кидай у мене сніжку. Я злопам'ятна.", "Тиша. Сніг. Ідеально.", "Твої сліди криві. Але милі.")),
        Pet(52, "Зоряник", "Спокійний, схильний до самопізнання.",
            "Ніч — найкращий час для роздумів. Подивись угору: кожна зоря — чиєсь бажання, яке ще не збулося. Ясні морозні ночі найчесніші: видно все, навіть те, що всередині тебе.",
            "Прогулюйтесь протягом 15 хв ясними ночами взимку.", 1.0, R(steps = 1000, months = WINTER, hours = 23 to 5, weather = setOf(CLEAR)),
