        Pet(53, "Вандрик", "Любовний! Жук!",
            "Привіт, дорогий друже! Я Вандрик! Я ЛЮБЛЮ! Люблю тебе, люблю прогулянки, люблю сердечка, люблю... о, як чудово ти йдеш! Хочеш валентинку? Я намалював її лапками. Усіма шістьма.",
            "Прогулюйтесь протягом 15 хв на день Валентина.", 1.0, R(steps = 1000, holiday = Holiday.VALENTINE),
            listOf("Жук? Так. Закоханий? Завжди!", "Тримай сердечко! І ще одне!", "Любов — це коли гуляєш удвох.")),
        Pet(54, "Різдвян", "Приносить атмосферу різдва.",
            "Вітаю! Я радий вас бачити! Відчуваєте? Пахне хвоєю, кутею і дивом. Я приношу різдвяну атмосферу кожному, хто вийшов на вулицю цього чарівного дня.",
            "Прогулюйтесь протягом 15 хв на Різдво.", 1.0, R(steps = 1000, holiday = Holiday.CHRISTMAS),
            listOf("Дзень-дзелень! Чуєш дзвіночки?", "Найкращий подарунок — прогулянка разом.", "Щасливого Різдва!")),
        Pet(55, "Гарбузеня", "Безтурботне і жартівливе.",
            "Буууу! Ти злякався мене? Ні? Ну хоч трішечки? Я ж так старався: вирізав страшну усмішку, вставив свічку... Добре-добре, я не страшний. Я веселий! Цукерку будеш?",
            "Прогулюйтесь протягом 15 хв на Хелловін.", 1.0, R(steps = 1000, holiday = Holiday.HALLOWEEN),
            listOf("Цукерки або пустощі!", "Бу! Ну скажи, що злякався.", "Усередині я — суцільне насіння доброти.")),
        Pet(56, "Папоротеня", "Хитре!",
            "Але ж кого ми тут маємо! Шукаєш квітку папороті, так? Усі шукають. Хе-хе. Може, я знаю, де вона. А може, й ні. Купальська ніч — ніч загадок. Іди за мною... чи не йди.",
            "Прогулюйтесь протягом 15 хв на Свято Купала.", 1.0, R(steps = 1000, holiday = Holiday.KUPALA),
            listOf("Квітка папороті? Ніколи не чув. Хе-хе.", "Стрибай через вогнище! Ну, уявне.", "Хитрість — це просто розум із хвостиком.")),
        Pet(57, "Ельзимка", "Магічні здібності найпотужніші!",
            "З Новим роком! Опівночі моя магія найсильніша: я можу виконати одне бажання. Лише одне! Тож обирай уважно. Підказка: «більше прогулянок» — чудове бажання.",
            "Прогулюйтесь протягом 15 хв на Новий рік.", 1.0, R(steps = 1000, holiday = Holiday.NEW_YEAR),
            listOf("Абракадабра-новорічна!", "Бажання прийнято. Обробляється...", "Цей рік буде чарівним. Я перевірила.")),
        Pet(58, "Часомір", "Цілеспрямований і амбітний.",
            "Ти довго йшов до своєї мети... і дійшов! Я з'являюся лише тим, хто не зупиняється. Чотири тисячі кроків — це не жарт. Поважаю. Наступна ціль — вісім?",
            "Ніхто не знає коли можна зустріти.", 0.5, R(steps = 4000),
            listOf("Мета без кроків — просто мрія.", "Кожна хвилина — інвестиція.", "Не зупиняйся. Я заміряю.")),
        Pet(59, "Чичюк", "Можливо, якби він не одягався як бандит...",
            "Вітаю… Чим можу допомогти? Ні-ні, не тікай! Я не бандит, це просто осіння маска від вітру. І шарф. І капюшон. Насправді я дуже ввічливий. Можу підсвітити ліхтариком дорогу.",
            "Прогулюйтесь протягом 20 хв увечері восени.", 1.0, R(steps = 1400, months = AUTUMN, hours = 17 to 23),
            listOf("Я не грабіжник. Я просто стильний.", "Гаманець? Не треба. Я колекціоную жолуді.", "Темно? Тримайся поруч, я все бачу.")),
        Pet(60, "Дрімка", "Маленьке ніжне створіння.",
            "Вітаю. Рада бачити вас... *позіхає* Ой, вибачте. Я така маленька, що навіть кілометр для мене — кругосвітня подорож. Можна я трошки подрімаю у вас у кишені?",
            "Прогулюйтесь щонайменше 1 км.", 0.15, R(steps = 1300),
            listOf("Хр-р... Ой! Я не спала!", "Ще п'ять хвилиночок...", "Ти теплий. Як ковдрочка.")),
